'use strict';

/* ------------------------------------------------------------------ utils */
const $  = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c =>
  ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
const won = n => n.toLocaleString('ko-KR') + '원';
const manwon = n => (n % 10000 === 0 ? (n / 10000) + '만원' : won(n));


/* ==========================================================================
   THEME  —  키 컬러 하나로 파생 토큰 전체를 계산
   setTheme('#101d66') 한 줄이면 앱 전체 색이 바뀝니다.
   ========================================================================== */
const clamp01 = (v, a, b) => Math.max(a, Math.min(b, v));
function hexToRgb(hex) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map(c => c + c).join('') : h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function hexToHsl(hex) {
  let [r, g, b] = hexToRgb(hex).map(v => v / 255);
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn;
  let h = 0; const l = (mx + mn) / 2;
  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
  if (d !== 0) {
    if (mx === r) h = ((g - b) / d) % 6;
    else if (mx === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60; if (h < 0) h += 360;
  }
  return [h, s, l];
}
function hslHex(h, s, l) {
  s = clamp01(s, 0, 1); l = clamp01(l, 0, 1);
  const c = (1 - Math.abs(2 * l - 1)) * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = l - c / 2;
  let r = 0, g = 0, b = 0;
  if (h < 60) [r, g, b] = [c, x, 0]; else if (h < 120) [r, g, b] = [x, c, 0];
  else if (h < 180) [r, g, b] = [0, c, x]; else if (h < 240) [r, g, b] = [0, x, c];
  else if (h < 300) [r, g, b] = [x, 0, c]; else [r, g, b] = [c, 0, x];
  return '#' + [r, g, b].map(v => Math.round((v + m) * 255).toString(16).padStart(2, '0')).join('');
}
function relLum(hex) {
  return hexToRgb(hex).map(v => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); })
    .reduce((a, v, i) => a + v * [.2126, .7152, .0722][i], 0);
}
function contrast(a, b) {
  const [x, y] = [relLum(a), relLum(b)].sort((p, q) => q - p);
  return (x + .05) / (y + .05);
}

const THEME = { key:'#5A79DB', wing:'#5A79DB', wingLight:'#879EE8', propDark:'#284BB8', accent:'#879EE8' };
function setTheme(hex) {
  if (!/^#?[0-9a-fA-F]{6}$/.test(hex)) return;
  hex = hex[0] === '#' ? hex.toLowerCase() : '#' + hex.toLowerCase();
  const [h, s0, l] = hexToHsl(hex);
  const s = Math.max(s0, .35);
  const v = {
    '--pri': hex,
    '--pri-dark': hslHex(h, s, Math.max(.09, l - .10)),
    '--pri-weak': hslHex(h, Math.min(.88, s), .945),
    '--pri-weak2': hslHex(h, Math.min(.88, s), .975),
    '--pri-tint': hslHex(h, Math.min(.80, s), .872),
    '--pri-soft': hslHex(h, Math.min(.72, s), .895),
    '--pri-soft2': hslHex(h, Math.min(.72, s), .945),
    '--pri-ink': hslHex(h, Math.min(.78, s), clamp01(l - .06, .24, .40)),
    '--accent': hslHex(h, Math.max(.68, s), .72),
    '--card-a': hslHex(h, s, clamp01(l, .30, .46)),
    '--card-b': hslHex(h, s, clamp01(l - .14, .15, .30)),
    '--hero-1': hslHex(h + 20, Math.min(.50, s), .085),
    '--hero-2': hslHex(h + 22, Math.min(.52, s), .225),
    '--hero-3': hslHex(h + 24, Math.min(.58, s), .50),
    '--deep-1': hslHex(h, Math.min(.55, s), .065),
    '--deep-2': hslHex(h, Math.min(.62, s), .185),
    '--ai-1': hslHex(h, Math.min(.55, s), .055),
    '--ai-2': hslHex(h, Math.min(.60, s), .165),
    '--glow': hexToRgb(hex).join(',')
  };
  const root = document.documentElement;
  Object.keys(v).forEach(k => root.style.setProperty(k, v[k]));
  THEME.key = hex;
  THEME.accent = v['--accent'];
  THEME.wing = hslHex(h, Math.max(.62, s), clamp01(l, .46, .62));
  THEME.wingLight = v['--accent'];
  THEME.propDark = hslHex(h, s, clamp01(l - .08, .26, .44));
  return v;
}

