      <path d="M29 35h42c6.6 0 12 5.4 12 12v4c0 9.4-6.3 17-14.3 17-4.6 0-6.9-2.4-16.7-2.4S40.9 68 36.3 68C28.3 68 22 60.4 22 51v-4c0-6.6 5.4-12 12-12Z" fill="${c}"/>
