function prodPh(m, cls = '', style = '', fit = 'slice') {
  const src = (typeof PRODUCT_IMG !== 'undefined') && PRODUCT_IMG[m.id];
  if (src) return `<div class="ph prod-ph ${cls}" style="${style}">
    <img src="${src}" alt="" loading="lazy"
         style="width:100%;height:100%;object-fit:${fit === 'meet' ? 'contain' : 'cover'};display:block">
  </div>`;
  const id = 'pdg' + (_pdId++);
  const c = m.color || '#8A94A0';
  return `<div class="ph prod-ph ${cls}" style="${style}">
    <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid ${fit}">
      <defs>
        <linearGradient id="${id}" x1="0" y1="0" x2="0.3" y2="1">
          <stop offset="0" stop-color="#FBFCFD"/><stop offset="1" stop-color="#E4EAF0"/></linearGradient>
        <radialGradient id="${id}r" cx="0.32" cy="0.2" r="0.85">
          <stop offset="0" stop-color="#fff" stop-opacity=".9"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>
      </defs>
      <rect width="100" height="100" fill="url(#${id})"/>
      <rect width="100" height="100" fill="url(#${id}r)"/>
      ${prodArt(m.art, c)}
    </svg></div>`;
}

