const evOf = id => EVENTS.find(e => e.id === id);
const evPlaceKo = e => {
  const r = RESORTS.find(x => x.id === e.resort);
  return r ? r.name : (e.placeShort || e.place);
};
const EV_PLACES = Array.from(new Set(EVENTS.map(e => e.resort)))
  .map(id => ({ id, ko: evPlaceKo(EVENTS.find(e => e.resort === id)) }));
const evSaved = id => !!(S.evSaves && S.evSaves[id]);
const evSavedCount = () => Object.keys(S.evSaves || {}).filter(k => S.evSaves[k]).length;
const EV_REG_KO = { open:'접수중', soon:'접수 예정', closed:'접수 마감' };

let evTab = 'up', evKind = 'all', evPlace = 'all';

function evList(tab) {
  let a = EVENTS.filter(e => e.st === (tab || evTab));
  if (evKind !== 'all') a = a.filter(e => e.kind === evKind);
  if (evPlace !== 'all') a = a.filter(e => e.resort === evPlace);
  return a;
}
function evCover(e, cls = '', style = '', variant = 'card') {
  if (e.official) {
    return `<div class="ph ev-official eo-${variant} ${cls}" style="${style}">
      <i class="eo-lines"></i>
      ${variant === 'hero' ? '' : (variant === 'card'
        ? `<span class="eo-slogan">${esc(e.slogan || '')}</span>`
        : '<span class="logo light eo-logo"></span>')}
    </div>`;
  }
  const r = RESORTS.find(x => x.id === e.resort);
  return r ? resortPh(r, cls, style) : ph('mountain', 7, cls, style);
}

/* 홈 가로 스크롤 카드 */
function evCard(e) {
  return `<button class="ev-card ${e.official ? 'official' : ''}" data-go="event:${e.id}">
    <span class="ev-cover">${evCover(e, '', '', 'card')}
      <i class="ev-dday">D-${e.dday}</i>
      ${e.official ? '<i class="ev-host">HI WINTER 주최</i>' : ''}</span>
    <span class="ev-b">
      <span class="ev-k">${ic('trophy', 11, 2.1)}${esc(EV_KO(e.kind))}</span>
      <span class="ev-n">${esc(e.n)}</span>
      <span class="ev-m">${esc(e.date)} · ${esc(evPlaceKo(e))}</span>
      <span class="ev-reg ${e.reg}">${EV_REG_KO[e.reg]}${e.reg === 'open' ? ` · 마감 D-${e.regDday}` : ''}</span>
    </span></button>`;
}

/* 목록 행 */
function evRow(e) {
  const rname = evPlaceKo(e);
  const done = e.st === 'done';
  return `<button class="ev-row" data-go="event:${e.id}">
    ${evCover(e, '', 'width:74px;height:74px;border-radius:14px;flex:none', 'row')}
    <span class="er-m">
      <span class="er-top">${e.official ? '<span class="tag dark">HI WINTER</span>' : ''}<span class="tag">${esc(EV_KO(e.kind))}</span>
        ${done ? '<span class="tag gray">종료</span>' : `<span class="ev-reg ${e.reg}">${EV_REG_KO[e.reg]}</span>`}</span>
      <span class="er-n">${esc(e.n)}</span>
      <span class="er-s">${ic('cal', 12, 2)}${esc(e.date)}<i class="dotsep"></i>${ic('pin', 12, 2)}${esc(rname)}</span>
    </span>
    ${done ? ic('right', 18, 2) : `<span class="er-d">D-${e.dday}</span>`}</button>`;
}

V.events = () => {
  const list = evList();
  const places = EV_PLACES;
  return `
  ${barHdr('대회 일정', `<button class="icon-btn" data-go="myevents">${ic('bookmark', 21)}</button>`)}
  <div class="scroll" style="padding-bottom:0">
    <div class="seg" style="position:sticky;top:0;z-index:4">
      <button class="${evTab === 'up' ? 'on' : ''}" data-act="evTab|up">다가오는 대회</button>
      <button class="${evTab === 'done' ? 'on' : ''}" data-act="evTab|done">지난 대회 결과</button>
    </div>
    <div style="background:#fff;padding:12px 0 13px;border-bottom:1px solid var(--line)">
      <div class="chips">
        ${EV_KINDS.map(k => `<button class="chip ${evKind === k.k ? 'on pri' : ''}" data-act="evKind|${k.k}">${k.ko}</button>`).join('')}
      </div>
      <div class="chips" style="margin-top:7px">
        <button class="chip ${evPlace === 'all' ? 'on' : ''}" data-act="evPlace|all">전체 장소</button>
        ${places.map(r => `<button class="chip ${evPlace === r.id ? 'on' : ''}" data-act="evPlace|${r.id}">${esc(r.ko)}</button>`).join('')}
      </div>
    </div>
    <div style="background:#fff">
      ${list.length ? list.map(evRow).join('')
        : empt('cal', '조건에 맞는 대회가 없어요', '종목이나 스키장 필터를 바꿔보세요.',
               '<button class="btn ghost" data-act="evClear">필터 초기화</button>')}
    </div>
    <div style="height:22px"></div>
  </div>`;
};

V.event = (p) => {
  const e = evOf(p.id); if (!e) return `${barHdr('대회')}<div class="scroll">${empt('cal', '대회를 찾을 수 없어요', '목록에서 다시 선택해주세요.')}</div>`;
  const rname = evPlaceKo(e);
  const done = e.st === 'done';
  const sv = evSaved(e.id);
  const info = done
    ? [['일시', e.dates], ['장소', e.place], ['종목', EV_KO(e.kind)], ['주최', e.host], ['규모', e.entrants], ['시상', e.prize]]
    : [['일시', e.dates], ['장소', e.place], ['종목', EV_KO(e.kind)], ['참가 자격', e.elig],
       ['참가비', e.feeLabel || won(e.fee)], ['모집 규모', e.slots], ['주최', e.host], ['시상', e.prize]];
  return `
  ${barHdr('대회 상세', `<button class="icon-btn" data-act="evSave|${e.id}">${ic(sv ? 'bookmarkF' : 'bookmark', 21)}</button>`)}
  <div class="scroll">
    <div class="ev-hero ${e.official ? 'official' : ''}">${evCover(e, '', 'width:100%;height:100%', 'hero')}
      <div class="ev-shade"></div>
      <div class="ev-htx">
        <span class="ev-hk">${e.official ? 'HI WINTER 주최 · ' : ''}${esc(EV_KO(e.kind))}${done ? ' · 종료' : ` · D-${e.dday}`}</span>
        ${e.slogan ? `<span class="ev-slogan">${esc(e.slogan)}</span>` : ''}
        <h2>${esc(e.n)}</h2>
        <p>${ic('cal', 13, 2)}${esc(e.date)}<i class="dotsep"></i>${ic('pin', 13, 2)}${esc(rname)}</p>
      </div>
    </div>

    ${done ? '' : `<div class="ev-reg-card ${e.reg}">
      <div class="erc-l"><span class="erc-k">${EV_REG_KO[e.reg]}</span>
        <b>${esc(e.regTerm)}</b>
        <span class="erc-s">${e.reg === 'open' ? `접수 마감까지 D-${e.regDday}` : `접수 시작까지 D-${e.regDday}`}</span></div>
      <button class="btn sm ${e.reg === 'open' ? '' : 'ghost'}" data-act="evApply|${e.id}">
        ${e.reg === 'open' ? '접수하기' : '접수 알림'}</button>
    </div>`}

    <p class="ev-sum">${esc(e.sum)}</p>

    <div class="card ev-info">
      ${info.filter(r => r[1]).map(([k, v]) => `<div class="eri"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}
    </div>

    ${done && e.winners ? `<div class="sec">
      ${secHead('입상자')}
      <div class="card ev-win">
        ${e.winners.map(([r, n, t]) => `<div class="ew"><span class="ew-r r${r}">${r}</span>
          <span class="ew-n">${esc(n)}</span><span class="ew-t">${esc(t)}</span></div>`).join('')}
      </div></div>` : ''}

    ${e.sched ? `<div class="sec">
      ${secHead('진행 일정')}
      <div class="card ev-sch">
        ${e.sched.map(([t, d]) => `<div class="es"><span class="es-t">${esc(t)}</span><span class="es-d">${esc(d)}</span></div>`).join('')}
      </div></div>` : ''}

    ${e.note ? `<div class="ev-note">${ic('info', 15, 2)}<span>${esc(e.note)}</span></div>` : ''}

    ${done ? '' : `<div class="sec">
      <button class="card card-btn ev-mate" data-act="evMate|${e.id}">
        <span class="em-ic">${ic('users', 21)}</span>
        <span class="em-tx"><b>이 대회 같이 갈 사람 구하기</b>
          <i>라이딩 메이트 글을 대회 정보가 채워진 상태로 작성해요</i></span>
        ${ic('right', 18, 2)}</button>
    </div>`}

    <p class="ev-src">본 프로토타입의 대회 정보는 샘플 데이터입니다.</p>
    <div style="height:18px"></div>
  </div>`;
};

V.myevents = () => {
  const list = EVENTS.filter(e => evSaved(e.id));
  return `${barHdr('관심 대회')}<div class="scroll">
    ${list.length ? `<div style="background:#fff;border-bottom:1px solid var(--line)">${list.map(evRow).join('')}</div>`
      : empt('bookmark', '저장한 대회가 없어요', '대회 상세에서 북마크를 눌러 저장해보세요.',
             '<button class="btn" data-go="events">대회 일정 보기</button>')}
    <div style="height:20px"></div></div>`;
};

/* ==========================================================================
   SEARCH
   ========================================================================== */
let SQ = '';
V.search = () => {
  const q = SQ.trim();
  const posts = q ? allPosts().filter(p => (p.t + p.d + p.resort).indexOf(q) >= 0) : [];
  const prods = q ? allProducts().filter(m => (m.n + m.area).indexOf(q) >= 0) : [];
  const res = q ? RESORTS.filter(r => r.name.indexOf(q) >= 0) : [];
  const evs = q ? EVENTS.filter(e => (e.n + EV_KO(e.kind) + e.place).indexOf(q) >= 0) : [];
  const none = q && !posts.length && !prods.length && !res.length && !evs.length;
  return `
  <header class="hdr bar"><button class="icon-btn" data-back>${ic('left', 23)}</button>
    <div class="searchbar" style="flex:1;height:42px">${ic('search', 18, 2)}
      <input id="sq" placeholder="장비, 웨어, 시즌방, 대회, 라이딩 메이트 검색" value="${esc(SQ)}">
      ${SQ ? `<button data-act="clearQ" style="color:#C3C9D0">${ic('x', 16, 2.4)}</button>` : ''}</div>
  </header>
  <div class="scroll">
    ${!q ? `<div class="sec" style="margin-top:14px">${secHead('최근 검색어')}
        <div class="recent">${S.recent.length ? S.recent.map(r =>
          `<span class="rc">${esc(r)}<button data-act="delRecent|${esc(r)}">${ic('x', 13, 2.6)}</button></span>`).join('')
          : '<span style="font-size:13px;color:var(--sub-2);font-weight:500">최근 검색어가 없어요.</span>'}</div></div>
      <div class="sec">${secHead('인기 검색어')}
        <div class="trend">${TRENDS.map((t, i) => `<button class="tr" data-act="trend|${esc(t)}"><i>${i + 1}</i>${esc(t)}</button>`).join('')}</div></div>`
    : none ? empt('search', `'${esc(q)}' 검색 결과가 없어요`, '다른 키워드로 검색해보세요.')
    : `${res.length ? `<div class="sec" style="margin-top:12px">${secHead('스키장')}
          <div class="card" style="margin:0 20px;overflow:hidden">${res.map(r => `<button class="row" data-go="resort:${r.id}">
            ${resortPh(r, '', 'width:44px;height:44px;border-radius:12px')}
            <span class="rw-main"><span class="rw-t">${esc(r.name)}</span><span class="rw-s">${esc(r.region)} · D-${r.dday}</span></span>
            ${ic('right', 18, 2)}</button>`).join('')}</div></div>` : ''}
      ${evs.length ? `<div class="sec">${secHead(`대회 ${evs.length}`, '전체보기', 'data-go="events"')}
          <div style="background:#fff;border-top:1px solid var(--line)">${evs.map(evRow).join('')}</div></div>` : ''}
      ${prods.length ? `<div class="sec">${secHead(`상품 ${prods.length}`, 'MARKET', 'data-go="market"')}
          <div class="hscroll">${prods.map(prodCard).join('')}</div></div>` : ''}
      ${posts.length ? `<div class="sec">${secHead(`게시글 ${posts.length}`)}
          <div style="background:#fff;border-top:1px solid var(--line);border-bottom:1px solid var(--line)">${posts.map(postCard).join('')}</div></div>` : ''}`}
    <div style="height:24px"></div>
  </div>`;
};

/* ==========================================================================
   FILTER STATE  +  helpers used by views
   ========================================================================== */
let cmResort = 'all', mkSort = 'new';
if (!S.cmts) S.cmts = {};
function sortProducts(a) {
  const l = a.slice();
  if (mkSort === 'low') l.sort((x, y) => x.p - y.p);
  else if (mkSort === 'high') l.sort((x, y) => y.p - x.p);
  return l;
}
const today = () => { const d = new Date(); return `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`; };
const uid = pre => pre + Math.random().toString(36).slice(2, 8);
const ART_BY_CAT = { mate:'rider', house:'room', info:'slope', qna:'lift', outfit:'jacket', gear:'deck', market:'gear' };
function addRecent(q) {
  q = q.trim(); if (!q) return;
  S.recent = [q].concat(S.recent.filter(r => r !== q)).slice(0, 8); save();
}

/* search input focus handling */
const _search = V.search;
V.search = p => {
  onMount(() => {
    const el = $('#sq'); if (!el) return;
    el.focus(); try { el.setSelectionRange(el.value.length, el.value.length); } catch (e) {}
    el.addEventListener('input', ev => { SQ = ev.target.value; refresh(); });
    el.addEventListener('keydown', ev => { if (ev.key === 'Enter') { addRecent(SQ); refresh(); } });
  });
  return _search(p);
};

